// Retire the root service worker installed by the former Chirpy site.
// Keep this URL: existing browsers update /sw.min.js without loading Astro.
self.addEventListener('install', (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const home = new URL('/', self.location.origin).href;
    for (const name of await caches.keys()) {
      if (!/^chirpy-\d+$/.test(name)) continue;
      const cache = await caches.open(name);
      // A different project on this github.io origin may also use Chirpy.
      // Only the old root site's cache precaches this exact homepage.
      if (await cache.match(home)) await caches.delete(name);
    }
    await self.clients.claim();
    await self.registration.unregister();
  })());
});

// No fetch listener and no forced navigation. Chirpy's existing
// controllerchange listener refreshes its old page once; current Astro pages
// keep their state and subsequent requests go directly to the network.
